        // Shown when an NKit source cannot be handled (an encoded NKit that was not decoded
        // up-front by NKitAsIso). Migrated here from the removed FsNKitFormat.
        public const string NKitExceptionMessage = "Image not supported. Use NKit v1 to Convert to ISO";

        static WiiConsts()
        {
            for (int i = 0; i < PublicKeyModulus.Length; i++) //decode WIT encoded Wii Public Key
            {
                PublicKeyModulus[i] = (byte)(PublicKeyModulus[i] ^ 0xdc);
                PublicKeyModulusRvtR[i] = (byte)(PublicKeyModulusRvtR[i] ^ 0xdc);
            }
        }

