        public static byte[] PublicKeyModulusNKit4096
        {
            get
            {
                XmlDocument doc = new XmlDocument();
                doc.LoadXml(WiiConsts.PrivateKeyPemNKit4096);
                return Convert.FromBase64String(doc.DocumentElement.SelectSingleNode("./Modulus").InnerText);
            }
        }

        public static byte[] PublicKeyModulusNKit2048
        {
            get
            {
                XmlDocument doc = new XmlDocument();
                doc.LoadXml(WiiConsts.PrivateKeyPemNKit2048);
                return Convert.FromBase64String(doc.DocumentElement.SelectSingleNode("./Modulus").InnerText);
            }
        }

        public static string PrivateKeyPemNKit4096 =
@"<RSAKeyValue>
  <Modulus></Modulus>
  <Exponent>AQAB</Exponent>
  <P></P>
  <Q></Q>
  <DP></DP>
  <DQ></DQ>
  <InverseQ></InverseQ>
  <D></D>
</RSAKeyValue>";

